//PBR
vec3 cam_pos = vec3(0.0, 0.0, 5.0);
vec3 view_dir = vec3(0.0, 0.0, -1.0);
vec3 light_pos = vec3(-2.0, 2.0, 5.0);
//Albedo of the mesh
vec3 albedo = vec3(1.0, 0.0, 0.0);
vec3 emmisive = vec3(0.0);
vec3 light_color = vec3(1.0);
//Base Reflectance
vec3 F0 = vec3(0.04);

float roughness = 0.3;
float metalness = 0.2;
float alpha;
#define PI 3.1415926535897

vec3 F(vec3 F0, vec3 V, vec3 H)
{
    float thetaPI = pow(1.0 - max(0.0, dot(V, H)), 5.0);
    return F0 + (1.0 - F0) * thetaPI;
}

float Gsub(vec3 N, vec3 X, float a)
{
    float k = a / 2.0;

    float NdotX = max(0.0, dot(N, X));

    return (NdotX) / max((NdotX * (1.0 - k) + k), 0.000001);
}
float G(vec3 N, vec3 V, vec3 L, float a)
{
    return Gsub(N, V, a) * Gsub(N, L, a);
}
float D(vec3 N, vec3 H, float a)
{
    a *= a;
    float NdotH = max(0.0, dot(N, H));
    float NdotH2 = NdotH * NdotH;
    return (a) / (max((PI * pow(((NdotH2) * (a - 1.0) + 1.0), 2.0)), 0.000001));
}
vec3 calculate_lighting(vec3 p, vec3 n)
{
    //normal vec
    vec3 N = normalize(n);
    //Light direction
    vec3 L = normalize(light_pos - p);
    //View Direction
    vec3 V = normalize(cam_pos - p);
    //Halfway vector
    vec3 H = normalize(V + L);
    //roughness alpha

    float alpha = roughness * roughness;

    F0 = mix(F0, albedo, metalness);
    vec3 Ks = F(F0, V, H);
    vec3 Kd = vec3(1.0) - Ks;

    vec3 lambert = albedo / PI;

    float cookTorrenceDenom = 4.0 * dot(V, N) * dot(L, N);
    cookTorrenceDenom = max(cookTorrenceDenom, 0.0001);
    lambert *= Kd;
    vec3 cookTorrence = (G(N, V, L, alpha) * D(N, H, alpha) * F(F0, V, H)) / (cookTorrenceDenom);

    vec3 BRDF = lambert + cookTorrence;

    vec3 final_color = emmisive + BRDF * light_color * max(dot(N, L), 0.0);
    return final_color + vec3(0.01) * albedo;
}

