//Ray marching
float sdf_sphere(vec3 p, vec3 c, float r)
{
    return length(p - c) - r;
}

float sample_world(vec3 p)
{
    float sphere0 = sdf_sphere(p, vec3(0.0), 2.0);
    return sphere0;
}
vec3 calculate_normal(vec3 p) {
    const float EPS = 0.001;

    vec3 v1 = vec3(sample_world(p + vec3(EPS, 0.0, 0.0)), sample_world(p + vec3(0.0, EPS, 0.0)), sample_world(p + vec3(0.0, 0.0, EPS)));
    vec3 v2 = vec3(sample_world(p - vec3(EPS, 0.0, 0.0)), sample_world(p - vec3(0.0, EPS, 0.0)), sample_world(p - vec3(0.0, 0.0, EPS)));

    return normalize(v1 - v2);
}
vec3 ray_march(vec3 ro, vec3 rd)
{
    const float MIN_DIST = 0.01;
    const float MAX_DIST = 1000.0;
    const int STEPS = 100;

    float dist_traveled = 0.0;
    vec3 cur_pos;

    for (int i = 0; i < STEPS; i++)
    {
        cur_pos = ro + dist_traveled * rd;

        float dist = sample_world(cur_pos);

        if (dist <= MIN_DIST)
        {
            vec3 normal = calculate_normal(cur_pos);

            return calculate_lighting(cur_pos, normal);
        }
        if (dist >= MAX_DIST)
            break;
        dist_traveled += dist;
    }

    return vec3(0.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;
    light_pos=vec3(4.0*sin(iTime), 2.0, 4.0*cos(iTime));

    vec3 color = ray_march(cam_pos, vec3(uv, -1.0));

    color.x = pow(color.x, 1.0 / 2.2);
    color.y = pow(color.y, 1.0 / 2.2);
    color.z = pow(color.z, 1.0 / 2.2);
    fragColor = vec4(color, 1.0);
}
